:root { --bg:#1e1e2e; --panel:#f4e4ba; --ink:#2e2a24; --accent:#e43b44; --shadow:#000; }
* { box-sizing:border-box; margin:0; padding:0; }
body { background:var(--bg); font-family:"Courier New", Courier, monospace; min-height:100vh; display:flex; align-items:center; justify-content:center; }
.app { background:var(--panel); border:4px solid var(--shadow); box-shadow:8px 8px 0 #000; padding:20px; width:min(90vw,420px); }
h1 { font-size:2rem; text-transform:uppercase; margin-bottom:14px; color:var(--ink); text-shadow:3px 3px 0 #f6c445; }
label { display:block; margin-bottom:6px; font-weight:bold; }
.input-row { display:flex; gap:8px; margin-bottom:16px; }
input[type="text"] { flex:1; padding:10px; border:3px solid var(--shadow); font:inherit; background:#fff; box-shadow:inset -3px -3px 0 #aaa; }
button { font:inherit; padding:10px 14px; border:3px solid var(--shadow); background:#f6c445; cursor:pointer; box-shadow:3px 3px 0 #000; }
button:active { box-shadow:none; transform:translate(3px,3px); }
.counts { display:flex; justify-content:space-between; margin-bottom:16px; background:#fff; border:3px solid var(--shadow); padding:8px; }
.counts p { font-weight:bold; }
#todo-list { list-style:none; display:flex; flex-direction:column; gap:10px; max-height:50vh; overflow-y:auto; }
.task { display:flex; align-items:center; gap:10px; padding:10px; background:#fffdf5; border:3px solid var(--shadow); box-shadow:4px 4px 0 #6b5b3e; }
.task input[type="checkbox"] { width:20px; height:20px; accent-color:#2e8b57; cursor:pointer; }
.task .todo-text { flex:1; overflow-wrap:anywhere; }
.task .todo-text.done { text-decoration:line-through; opacity:.6; }
.task button { padding:6px 8px; background:var(--accent); color:#fff; box-shadow:2px 2px 0 #000; }
button:focus-visible, input:focus-visible, .task input:focus-visible { outline:3px dashed #f6c445; outline-offset:2px; }

(() => {
  const input = document.getElementById('todo-input');
  const addBtn = document.getElementById('todo-add');
  const totalEl = document.getElementById('todo-total');
  const remainingEl = document.getElementById('remaining');
  const listEl = document.getElementById('todo-list');
  const tasks = [];
  let nextId = 1;

  const updateCounts = () => {
    totalEl.textContent = String(tasks.length);
    remainingEl.textContent = String(tasks.filter(t => !t.done).length);
  };

  const renderTask = (task) => {
    const li = document.createElement('li');
    li.className = 'task';

    const textSpan = document.createElement('span');
    textSpan.id = `todo-text-${task.id}`;
    textSpan.className = 'todo-text' + (task.done ? ' done' : '');
    textSpan.textContent = task.text;

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `todo-check-${task.id}`;
    checkbox.checked = task.done;
    checkbox.setAttribute('aria-label', `Mark task ${task.text} as done`);
    checkbox.addEventListener('change', () => {
      task.done = checkbox.checked;
      textSpan.classList.toggle('done', task.done);
      updateCounts();
    });

    const deleteBtn = document.createElement('button');
    deleteBtn.type = 'button';
    deleteBtn.id = `todo-delete-${task.id}`;
    deleteBtn.textContent = 'Delete';
    deleteBtn.setAttribute('aria-label', `Delete task ${task.text}`);
    deleteBtn.addEventListener('click', () => {
      const index = tasks.indexOf(task);
      if (index !== -1) tasks.splice(index, 1);
      li.remove();
      updateCounts();
    });

    li.append(checkbox, textSpan, deleteBtn);
    listEl.appendChild(li);
  };

  const addTask = () => {
    const text = input.value.trim();
    if (!text) {
      input.value = '';
      return;
    }
    const task = { id: nextId++, text, done: false };
    tasks.push(task);
    renderTask(task);
    input.value = '';
    input.focus();
    updateCounts();
  };

  addBtn.addEventListener('click', addTask);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      addTask();
    }
  });

  updateCounts();
})();
